const geo = $input.first().json;
const cfg = $('Set Search Inputs').first().json;
if (!geo || !geo.lat || !geo.lon) {
  throw new Error('Geocoding returned no coordinates for "' + cfg.location + '". Try a more specific location (e.g. "Des Moines, Iowa, USA").');
}
return [{ json: {
  niche: cfg.niche,
  location: cfg.location,
  latitude: parseFloat(geo.lat),
  longitude: parseFloat(geo.lon),
  radius_meters: Math.min(cfg.radius_meters || 3000, 3000), // FREE SAMPLE cap: 3,000 m
  max_results: Math.min(cfg.max_results || 25, 25), // FREE SAMPLE cap: 25 results
  user_agent: cfg.user_agent
} }];

const input = $input.first().json;

// Example niche -> OpenStreetMap tag mapping (sample set).
// Full tag reference: OpenStreetMap Wiki "Map features".
const NICHE_MAP = {
  // FREE SAMPLE: 6 example niches. The paid version ships the full NICHE_MAP (25+ niches).
  dentist: ['amenity', 'dentist'],
  restaurant: ['amenity', 'restaurant'],
  cafe: ['amenity', 'cafe'],
  coffee: ['amenity', 'cafe'],
  plumber: ['craft', 'plumber'],
  salon: ['shop', 'beauty'],
  gym: ['leisure', 'fitness_centre']
};

const key = String(input.niche || '').toLowerCase().trim().replace(/[\s-]+/g, '_');
const tag = NICHE_MAP[key] || ['amenity', key];

const query = '[out:json][timeout:60];\n'
  + '(\n'
  + '  node["' + tag[0] + '"="' + tag[1] + '"](around:' + input.radius_meters + ',' + input.latitude + ',' + input.longitude + ');\n'
  + '  way["' + tag[0] + '"="' + tag[1] + '"](around:' + input.radius_meters + ',' + input.latitude + ',' + input.longitude + ');\n'
  + ');\n'
  + 'out center tags;';

return [{ json: Object.assign({}, input, {
  osm_tag_key: tag[0],
  osm_tag_value: tag[1],
  query: query
}) }];

const elements = ($input.first().json.elements) || [];
const cfg = $('Set Search Inputs').first().json;
const max = Math.min(cfg.max_results || 25, 25); // FREE SAMPLE cap: 25 results
const leads = [];
for (const el of elements) {
  if (leads.length >= max) break;
  const tags = el.tags || {};
  const name = tags.name;
  if (!name) continue; // skip unnamed map features
  const addrParts = [tags['addr:housenumber'], tags['addr:street'], tags['addr:city'], tags['addr:postcode']].filter(Boolean);
  leads.push({
    business_name: name,
    address: addrParts.join(' '),
    phone: tags.phone || tags['contact:phone'] || ''
    // FREE SAMPLE stops here on purpose: the paid Lead Finder also returns
    // website, email and coordinates — the fields outreach runs on.
  });
}
if (leads.length === 0) {
  throw new Error('No named businesses found. Try a different niche (see NICHE_MAP in "Build Overpass Query") or check that the location geocoded correctly. Note: the free sample searches a 3,000 m radius, so very spread-out areas return fewer results.');
}
return leads.map(function (l) { return { json: l }; });
